content:
Dựa trên tài liệu AWS Training and Certification tìm được, tôi sẽ tạo 10 flashcard từ các dịch vụ AWS được liệt kê:

[
  {
    "front": "Amazon EC2",
    "back": "Dịch vụ tính toán đám mây cung cấp máy chủ ảo có thể thay đổi kích thước."
  },
  {
    "front": "AWS Lambda",
    "back": "Dịch vụ tính toán không máy chủ cho phép chạy mã mà không cần quản lý máy chủ."
  },
  {
    "front": "Amazon RDS",
    "back": "Dịch vụ cơ sở dữ liệu quan hệ được quản lý, hỗ trợ nhiều công cụ cơ sở dữ liệu."
  },
  {
    "front": "Amazon DynamoDB",
    "back": "Cơ sở dữ liệu NoSQL được quản lý hoàn toàn cho ứng dụng yêu cầu hiệu suất cao."
  },
  {
    "front": "Amazon S3",
    "back": "Dịch vụ lưu trữ đối tượng đám mây với tính sẵn sàng cao và bền vững."
  },
  {
    "front": "AWS CloudFormation",
    "back": "Dịch vụ quản lý cho phép định mô tả và triển khai tài nguyên AWS bằng mã."
  },
  {
    "front": "Amazon CloudWatch",
    "back": "Dịch vụ giám sát cho phép theo dõi tài nguyên AWS và nhật ký ứng dụng."
  },
  {
    "front": "Amazon Athena",
    "back": "Dịch vụ truy vấn SQL để phân tích dữ liệu trực tiếp trong Amazon S3."
  },
  {
    "front": "Amazon SNS",
    "back": "Dịch vụ nhắn tin để gửi thông báo tới nhiều đối tượng nhận qua các giao thức khác nhau."
  },
  {
    "front": "AWS Auto Scaling",
    "back": "Dịch vụ tự động điều chỉnh sức mạnh tính toán dựa trên nhu cầu thay đổi."
  }
]
